//! ShieldTube native ad-blocking engine.
//!
//! Two ABI surfaces over one implementation:
//! * `ffi_c`   - C ABI (`st_*`), header generated by cbindgen into include/shieldtube.h.
//! * `ffi_jni` - `Java_*` JNI exports consumed by Kotlin `external fun`s.
//!
//! Both surfaces are string/JSON-in-out plus scalar booleans and an opaque
//! handle. No Rust struct is ever passed across the ABI (see VENDORED.md).

pub mod engine;
mod ffi_c;
mod ffi_jni;
